// storeDecimal keeps only low-order integer digits that fit, preserving scale.
func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// ensure scale
	// v already has correct scale but we normalize via StringFixed
	sign := ""
	if v.IsNegative() {
		sign = "-"
		v = v.Abs()
	}
	s := v.StringFixed(scale)
	// s is like "123.45" or "123" if scale 0
	var intPart, fracPart string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPart = parts[0]
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", int(scale))
		}
		if len(fracPart) < int(scale) {
			fracPart = fracPart + strings.Repeat("0", int(scale)-len(fracPart))
		} else if len(fracPart) > int(scale) {
			fracPart = fracPart[:scale]
		}
	} else {
		// no decimal point
		if dot := strings.Index(s, "."); dot >= 0 {
			intPart = s[:dot]
		} else {
			intPart = s
		}
		fracPart = ""
	}
	// intPart may have leading zeros; but for overflow we consider its digits
	// COBOL stores integer digits as digits, dropping high-order if too many.
	// So if len(intPart) > intDigits, keep rightmost intDigits
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	// rebuild
	var rebuilt string
	if scale > 0 {
		rebuilt = sign + intPart + "." + fracPart
	} else {
		rebuilt = sign + intPart
	}
	d, err := decimal.NewFromString(rebuilt)
	if err != nil {
		return decimal.RequireFromString(rebuilt)
	}
	return d
}

func formatEdited(v decimal.Decimal, pic string) string {
	// Split pic into integer and fractional picture
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	var fracDigitsNeeded int
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
		for _, c := range fracPic {
			if c == '9' || c == 'Z' {
				fracDigitsNeeded++
			}
		}
	} else {
		intPic = pic
		fracPic = ""
	}
	// fractional digits from value
	// Use absolute value; sign not needed for this program (all positive)
	av := v.Abs()
	// get string with required fractional scale
	var intPartStr, fracPartStr string
	if fracDigitsNeeded > 0 {
		s := av.StringFixed(int32(fracDigitsNeeded))
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", fracDigitsNeeded)
		}
	} else {
		// integer only
		s := av.StringFixed(0)
		if idx := strings.Index(s, "."); idx >= 0 {
			intPartStr = s[:idx]
		} else {
			intPartStr = s
		}
		fracPartStr = ""
	}
	// count digit placeholders in intPic
	intPlaceholders := 0
	for _, c := range intPic {
		if c == '9' || c == 'Z' {
			intPlaceholders++
		}
	}
	// overflow truncation: keep low-order digits
	if len(intPartStr) > intPlaceholders {
		intPartStr = intPartStr[len(intPartStr)-intPlaceholders:]
	}
	// pad with leading zeros to exactly intPlaceholders
	if len(intPartStr) < intPlaceholders {
		intPartStr = strings.Repeat("0", intPlaceholders-len(intPartStr)) + intPartStr
	}
	// Build int output chars filling digit placeholders in order
	intOut := make([]rune, len(intPic))
	dIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intOut[i] = rune(intPartStr[dIdx])
			dIdx++
		} else if ch == ',' {
			intOut[i] = ','
		} else {
			intOut[i] = ch
		}
	}
	// Apply Z suppression
	suppressed := true
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := intOut[i]
			if suppressed {
				if d == '0' {
					if ch == '9' {
						// print 0 and end suppression
						suppressed = false
					} else {
						intOut[i] = ' '
					}
				} else {
					suppressed = false
				}
			}
		} else if ch == ',' {
			if suppressed {
				intOut[i] = ' '
			}
		}
	}
	intOutStr := string(intOut)
	if fracPic != "" {
		// fracPartStr already correct length; map to fracPic (all 9s)
		// If fracPic had Z, similar but not needed here
		return intOutStr + "." + fracPartStr
	}
	return intOutStr
}

func formatPIC9(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if s[0] == '-' {
		// handle negative (not needed)
		sign := "-"
		num := s[1:]
		if len(num) > digits-1 {
			num = num[len(num)-(digits-1):]
		}
		if len(num) < digits-1 {
			num = strings.Repeat("0", digits-1-len(num)) + num
		}
		return sign + num
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func parseSalesRecord(line string) SalesRec {
	// pad with spaces to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12] // 8 digits
	// PIC 9(6)V99 => 8 digits, implied 2 decimals
	// digits only; spaces treated as zero? COBOL would have zeros. We'll trim spaces.
	trimmed := strings.TrimSpace(srSalesRaw)
	if trimmed == "" {
		trimmed = "0"
	}
	// keep only digits
	digitsOnly := ""
	for _, c := range trimmed {
		if c >= '0' && c <= '9' {
			digitsOnly += string(c)
		}
	}
	if digitsOnly == "" {
		digitsOnly = "0"
	}
	n, _ := decimal.NewFromString(digitsOnly)
	// shift -2
	d := decimal.New(n.IntPart(), -2)
	// Ensure scale 2 trunc? For input just construct
	// Store truncation to 6 int digits? Input is exactly 8 digits so fits
	return SalesRec{SrId: srId, SrSales: d}
}

